package com.petplan.service;
import com.petplan.repository.Datos; import com.petplan.service.CuentaService.Actor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.beans.factory.annotation.Value; import java.util.*; import static com.petplan.service.Reglas.*; import static com.petplan.service.CuentaService.*;
@Service public class VeterinariaService {
 private final Datos db; private final CuentaService cuentas; private final Map<Long,Long> admins=new HashMap<>();
 public VeterinariaService(Datos db,CuentaService cuentas,@Value("${petplan.admin-clinicas:}") String asignaciones){this.db=db;this.cuentas=cuentas;for(String par:asignaciones.split(",")){if(par.isBlank())continue;String[] v=par.strip().split(":");if(v.length!=2)throw new IllegalArgumentException("PETPLAN_ADMIN_CLINICAS: usuario:clinica");admins.put(Long.valueOf(v[0]),Long.valueOf(v[1]));}}
 public List<Map<String,Object>> listar(Actor a){return db.lista("SELECT * FROM veterinarias"+(a.rol().equals(SUPER)?"":" WHERE estado='Aprobada'")+" ORDER BY nombre");}
 @Transactional public long crear(Actor a,Map<String,Object>d){a.exige(SUPER);return db.insertar("INSERT INTO veterinarias(nit,nombre,contacto) VALUES(?,?,?)",texto(d,"nit",20,true),texto(d,"nombre",100,true),texto(d,"contacto",20,true));}
 @Transactional public void estado(Actor a,long id,Map<String,Object>d){a.exige(SUPER);String e=texto(d,"estado",20,true);if(!List.of("Aprobada","Rechazada","Inactiva","Pendiente").contains(e))throw invalido("Estado inválido");db.uno("SELECT codigo_veterinarias FROM veterinarias WHERE codigo_veterinarias=?",id);db.cambiar("UPDATE veterinarias SET estado=?,fecha_aprobacion=CASE WHEN ?='Aprobada' THEN COALESCE(fecha_aprobacion,CURDATE()) ELSE fecha_aprobacion END WHERE codigo_veterinarias=?",e,e,id);}
 public long clinica(Actor a){long c;if(a.rol().equals(VET))c=n(db.uno("SELECT codigo_veterinarias FROM veterinario WHERE codigo_usuario=?",a.id()),"codigo_veterinarias");else if(a.rol().equals(ADMIN)){Long x=admins.get(a.id());if(x==null)throw conflicto("Administrador sin veterinaria asignada en configuración");c=x;}else throw prohibido();aprobada(c);return c;}
 public void aprobada(long c){if(db.lista("SELECT codigo_veterinarias FROM veterinarias WHERE codigo_veterinarias=? AND estado='Aprobada'",c).isEmpty())throw conflicto("Veterinaria no disponible");}
 public List<Map<String,Object>> administradores(Actor a){a.exige(SUPER);return db.lista("SELECT codigo_usuario,nombres,apellidos,email,`user` FROM usuario WHERE UPPER(rol)='ADMINISTRADOR' ORDER BY codigo_usuario");}
 @Transactional public long crearAdmin(Actor a,Map<String,Object>d){a.exige(SUPER);return cuentas.crear(d,ADMIN);}
 public List<Map<String,Object>> veterinarios(Actor a){a.exige(ADMIN,SUPER);String sql="SELECT v.codigo_veterinario,v.nombres_vet,v.apellidos_vet,v.email_vet,v.num_contacto_vet,v.num_licencia,v.codigo_veterinarias,c.nombre veterinaria FROM veterinario v JOIN veterinarias c ON c.codigo_veterinarias=v.codigo_veterinarias";return a.rol().equals(SUPER)?db.lista(sql+" ORDER BY v.nombres_vet"):db.lista(sql+" WHERE v.codigo_veterinarias=? ORDER BY v.nombres_vet",clinica(a));}
 @Transactional public long crearVet(Actor a,Map<String,Object>d){a.exige(ADMIN,SUPER);long c=a.rol().equals(ADMIN)?clinica(a):id(d.get("codigo_veterinarias"));aprobada(c);long u=cuentas.crear(d,VET);return db.insertar("INSERT INTO veterinario(nombres_vet,apellidos_vet,num_contacto_vet,email_vet,num_licencia,codigo_usuario,codigo_veterinarias) VALUES(?,?,?,?,?,?,?)",texto(d,"nombres",80,true),texto(d,"apellidos",80,true),texto(d,"numero_contacto",20,true),texto(d,"email",120,true).toLowerCase(Locale.ROOT),texto(d,"num_licencia",30,true),u,c);}
 @Transactional public void editarVet(Actor a,long id,Map<String,Object>d){a.exige(ADMIN,SUPER);var r=db.uno("SELECT codigo_usuario,codigo_veterinarias FROM veterinario WHERE codigo_veterinario=?",id);if(a.rol().equals(ADMIN)&&n(r,"codigo_veterinarias")!=clinica(a))throw prohibido();long u=n(r,"codigo_usuario");String nom=texto(d,"nombres",80,true),ape=texto(d,"apellidos",80,true),tel=texto(d,"numero_contacto",20,true);db.cambiar("UPDATE usuario SET nombres=?,apellidos=?,numero_contacto=? WHERE codigo_usuario=?",nom,ape,tel,u);db.cambiar("UPDATE veterinario SET nombres_vet=?,apellidos_vet=?,num_contacto_vet=?,num_licencia=? WHERE codigo_veterinario=?",nom,ape,tel,texto(d,"num_licencia",30,true),id);}
}
